/**
 * "Who ruled this city?" — the states and peoples that held each city in
 * src/data/cities.json, as drawn in every map snapshot.
 *
 * cityRulers.json is generated by scripts/build-city-rulers.mts (it searches
 * all the snapshots, which is too slow to do per request). Re-run that script
 * after editing cities.json.
 */
import CITIES from "@/data/cities.json";
import RULERS from "@/data/cityRulers.json";
import { CITY_RULER_FIXES } from "@/data/cityRulerFixes";
import { resolveFeature } from "@/data/crosswalk";
import { SNAPSHOT_YEARS } from "@/data/snapshotYears";

export interface City {
  slug: string;
  name: string;
  country: string;
  lat: number;
  lng: number;
  /** Earlier names, comma-separated ("Byzantium, Constantinople"). */
  formerly?: string;
}

/** One stretch of snapshots in which the map draws the same ruler. */
export interface RulerSpan {
  /** First snapshot year that draws this ruler. */
  from: number;
  /** First later snapshot year that draws someone else; null if it still holds. */
  to: number | null;
  /** Territory name in the snapshot; null when the map draws no state here. */
  name: string | null;
  /** The power that territory answered to, when the map records a different one. */
  sovereign: string | null;
  /** Atlas page for the ruler, when we have one. */
  href?: string;
}

export const CITY_LIST: readonly City[] = [...(CITIES as City[])].sort((a, b) => a.name.localeCompare(b.name));

export function getCity(slug: string): City | undefined {
  return CITY_LIST.find((c) => c.slug === slug);
}

/**
 * A city's rulers, oldest first. Leading empty stretches (before anyone is
 * drawn there) are dropped; later gaps are kept, since "no state on the map"
 * is itself part of the story.
 */
export function rulersOf(slug: string): RulerSpan[] {
  const spans = applyFixes((RULERS as Record<string, RulerSpan[]>)[slug] ?? [], slug).flatMap(withLinks);
  const first = spans.findIndex((s) => s.name);
  return first === -1 ? [] : spans.slice(first);
}

/** The generated spans with src/data/cityRulerFixes.ts applied, neighbours with the same ruler merged. */
function applyFixes(raw: RulerSpan[], slug: string): RulerSpan[] {
  const fixes = CITY_RULER_FIXES[slug];
  if (!fixes) return raw;
  const end = (t: number | null) => t ?? Infinity;
  let spans = raw.map((s) => ({ ...s }));
  for (const f of fixes) {
    const cut: RulerSpan[] = [];
    for (const s of spans) {
      if (end(s.to) <= f.from || s.from >= end(f.to)) { cut.push(s); continue; }
      if (s.from < f.from) cut.push({ ...s, to: f.from });
      if (end(s.to) > end(f.to)) cut.push({ ...s, from: f.to! });
    }
    cut.push({ from: f.from, to: f.to, name: f.name, sovereign: f.sovereign ?? null });
    spans = cut.sort((a, b) => a.from - b.from);
  }
  const merged: RulerSpan[] = [];
  for (const s of spans) {
    const last = merged.at(-1);
    if (last && last.name === s.name && last.sovereign === s.sovereign) last.to = s.to;
    else merged.push(s);
  }
  return merged;
}

/**
 * Link a span to the ruler's atlas page. The same map name can mean different
 * states over a long span ("France" is a kingdom in 1783, a republic in 1800
 * and the modern state after 1815), so the span is split wherever the
 * year-aware crosswalk points somewhere else.
 */
export function withLinks(span: RulerSpan): RulerSpan[] {
  if (!span.name) return [span];
  const years = SNAPSHOT_YEARS.filter((y) => y >= span.from && (span.to === null || y < span.to));
  const out: RulerSpan[] = [];
  for (const year of years.length ? years : [span.from]) {
    const entry = resolveFeature(span.name, span.sovereign ?? span.name, year);
    const href = entry ? `/place/${entry.slug}` : undefined;
    const last = out.at(-1);
    if (last && last.href === href) continue;
    if (last) last.to = year;
    out.push({ ...span, from: year, href });
  }
  out[out.length - 1].to = span.to;
  return out;
}

/** Distinct ruler names, in order of first appearance. */
export function distinctRulers(spans: RulerSpan[]): string[] {
  return [...new Set(spans.flatMap((s) => (s.name ? [s.name] : [])))];
}

/** Great-circle distance in km, for "nearby cities". */
function distanceKm(a: City, b: City): number {
  const rad = Math.PI / 180;
  const dLat = (b.lat - a.lat) * rad;
  const dLng = (b.lng - a.lng) * rad;
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(a.lat * rad) * Math.cos(b.lat * rad) * Math.sin(dLng / 2) ** 2;
  return 2 * 6371 * Math.asin(Math.sqrt(h));
}

export function nearbyCities(city: City, count = 6): City[] {
  return CITY_LIST.filter((c) => c.slug !== city.slug)
    .map((c) => ({ c, d: distanceKm(city, c) }))
    .sort((x, y) => x.d - y.d)
    .slice(0, count)
    .map((x) => x.c);
}
